#include "gesture_cnn.h"
#include "weights.h"  // generated by export_weights.py: W1,B1,W2,B2,W3,B3,WD1,BD1,WD2,BD2

void gesture_cnn(const act_t x_in[T0 * C0], int &pred, logit_t logits[NCLASS]) {
#pragma HLS INTERFACE m_axi port = x_in offset = slave bundle = gmem depth = 220
#pragma HLS INTERFACE s_axilite port = x_in
#pragma HLS INTERFACE s_axilite port = pred
#pragma HLS INTERFACE m_axi port = logits offset = slave bundle = gmem depth = NCLASS
#pragma HLS INTERFACE s_axilite port = logits
#pragma HLS INTERFACE s_axilite port = return

    act_t x[T0][C0];
    act_t a1[T0][C1], p1[T1][C1];
    act_t a2[T1][C2], p2[T2][C2];
    act_t a3[T2][C3];
    act_t feat[NFEAT], h[FC1];
    logit_t lg[NCLASS];

    // Burst-read the window from DDR into on-chip memory.
    for (int t = 0; t < T0; t++) {
        for (int c = 0; c < C0; c++) {
#pragma HLS PIPELINE II = 1
            x[t][c] = x_in[t * C0 + c];
        }
    }

    conv1d_relu<T0, C0, C1, K1>(x, W1, B1, a1);
    maxpool2<T0, C1>(a1, p1);
    conv1d_relu<T1, C1, C2, K2>(p1, W2, B2, a2);
    maxpool2<T1, C2>(a2, p2);
    conv1d_relu<T2, C2, C3, K3>(p2, W3, B3, a3);
    global_pool<T2, C3>(a3, feat);
    dense<NFEAT, FC1, true>(feat, WD1, BD1, h);
    dense<FC1, NCLASS, false, logit_t>(h, WD2, BD2, lg);

    // Argmax (softmax is unnecessary for picking the class).
    int best = 0;
    for (int i = 1; i < NCLASS; i++) {
        if (lg[i] > lg[best]) best = i;
    }
    for (int i = 0; i < NCLASS; i++) {
#pragma HLS PIPELINE II = 1
        logits[i] = lg[i];
    }
    pred = best;
}
